    h,w=len(grid),len(grid[0])
    colors=[]
    # The repeated color bar is a horizontal list of colors, each repeated vertically.
    for c in range(w):
        vals=[grid[r][c] for r in range(h) if grid[r][c]]
        for v in vals:
            if vals.count(v)>=3 and v not in colors:
                colors.append(v)
                break
    # Find the shape by taking the component with the greatest horizontal span.
    cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]}
    comps=[]
    while cells:
        q=[cells.pop()]; comp=set(q)
        while q:
            r,c=q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells:
                    cells.remove(p); comp.add(p); q.append(p)
        comps.append(comp)
    shape=max(comps,key=lambda s:max(c for r,c in s)-min(c for r,c in s))
    r0=min(r for r,c in shape); c0=min(c for r,c in shape)
    rh=max(r for r,c in shape)-r0+1; cw=max(c for r,c in shape)-c0+1
    pat={(r-r0,c-c0) for r,c in shape}
    out=[[0]*w for _ in range(h)]
    # Keep the original object's vertical slot as the corresponding color in the stack.
    start=max(0,r0-(colors.index(next((v for v in colors if v==grid[r0][c0]),colors[0]))*rh))
    for k,col in enumerate(colors):
        for dr,dc in pat:
            rr=start+k*rh+dr; cc=c0+dc
            if rr<h and cc<w: out[rr][cc]=col
    return out
